-- =============================================================================================
-- 2600 bài viết trải đủ 8 giá trị PostType, kèm hashtag, gắn thẻ và ảnh.

-- Flyway chạy file này qua chính pool của ứng dụng, nơi application.yml đặt
-- statement_timeout = 15s cho MỌI kết nối. Trần đó đúng cho một request người dùng và sai cho một
-- lần nạp dữ liệu hàng chục nghìn hàng. LOCAL: chỉ có hiệu lực trong giao dịch của migration này,
-- không rò sang bất kỳ kết nối nào khác của ứng dụng — dùng `SET` trần sẽ nới trần cho cả
-- connection sau khi nó được trả về pool, tức vô hiệu hoá một lớp bảo vệ có chủ đích ở một chỗ
-- hoàn toàn không liên quan.
SET LOCAL statement_timeout = 0;

-- FILE NÀY SINH TỰ ĐỘNG bởi scripts/seed/generate_seed.py — sửa tay sẽ bị ghi đè.
--
-- Id cấp TƯỜNG MINH (100001-102600) chứ không để sequence tự sinh: V84-V92 phải trỏ tới từng bài cụ
-- thể — bình luận vào bài nào, sách gắn bài nào, log kiểm duyệt của bài nào. Để sequence cấp thì các
-- file sau phải dò lại bài bằng cách so khớp nội dung, vừa dài dòng vừa hỏng ngay khi ai sửa câu chữ.
--
-- Dải id theo loại:
--   EVENT         100001-100080  (80 bài)
--   CODE_SNIPPET  100081-100240  (160 bài)
--   ARTICLE       100241-100360  (120 bài)
--   QNA           100361-100560  (200 bài)
--   POLL          100561-100640  (80 bài)
--   LINK          100641-100760  (120 bài)
--   BOOK          100761-100840  (80 bài)
--   REGULAR       100841-102600  (1760 bài)
--
-- Ảnh dùng placeholder ${minioUrl} nên chạy đúng ở cả dev lẫn production. Object tương ứng do
-- `docker compose up` nạp (minio-seed-objects đọc key từ chính file này, minio-init tải lên). MỘT ảnh
-- cố ý mang key `khong-ton-tai` và KHÔNG được nạp — đó là fixture cho nhánh "ảnh không tải được".
--
-- Trạng thái kiểm duyệt cố ý không đồng nhất: /posts/public chỉ trả bài APPROVED, còn
-- /admin/moderation/pending cần bài PENDING_REVIEW mới có gì để trình bày.

-- =============================================================================================

-- ── Hashtag ──────────────────────────────────────────────────────────────────────────────────
-- usage_count được TÍNH LẠI từ t_post_hashtags ở cuối file, không gõ tay, để con số trên trang
-- hashtag luôn khớp với số bài thật sự gắn thẻ đó.


-- ── EVENT (100001-100080) ───────────────────────────────────────────────────────


-- ── CODE_SNIPPET (100081-100240) ────────────────────────────────────────────────


-- ── ARTICLE (100241-100360) ─────────────────────────────────────────────────────


-- ── QNA (100361-100560) ─────────────────────────────────────────────────────────


-- ── POLL (100561-100640) ────────────────────────────────────────────────────────


-- ── LINK (100641-100760) ────────────────────────────────────────────────────────


-- ── BOOK (100761-100840) ────────────────────────────────────────────────────────


-- ── REGULAR (100841-102600) ─────────────────────────────────────────────────────


-- ── Gắn hashtag vào bài ──────────────────────────────────────────────────────────────────────


-- ── Gắn thẻ người vào bài ────────────────────────────────────────────────────────────────────
-- Chỉ gắn thẻ người mà tác giả ĐÃ là bạn: gắn thẻ người lạ là thứ luồng thật không cho làm.


-- usage_count tính lại từ dữ liệu vừa chèn, không gõ tay.

UPDATE socialapp.t_hashtags h
   SET usage_count = COALESCE(c.total, 0)
  FROM (SELECT hashtag_id, COUNT(*) AS total
          FROM socialapp.t_post_hashtags GROUP BY hashtag_id) c
 WHERE c.hashtag_id = h.id;

-- ── Quiz gắn vào bài ─────────────────────────────────────────────────────────────────────────
-- quiz_details KHÔNG phải một PostType riêng: bất kỳ bài nào cũng mang được quiz, và QuizService chỉ
-- kiểm tra post.quizDetails có khác null hay không. Gắn vào bài REGULAR và ARTICLE cho giống cách
-- dùng thật.
--
-- Mỗi quiz đúng 3 câu. QuizService bắt bài nộp phải có SỐ ĐÁP ÁN BẰNG số câu hỏi, và V84 sinh bài
-- nộp dựa vào đúng con số đó — thêm câu ở đây mà quên sửa V84 là mọi bài nộp bị từ chối.
--
-- UPDATE chứ không thêm cột vào INSERT ở trên: chỉ 8 trong 2.600 bài có quiz, nên nhét thêm một cột
-- jsonb NULL vào mọi hàng chỉ làm file to ra mà không nói thêm điều gì.

UPDATE socialapp.t_posts p SET quiz_details = v.details
  FROM (VALUES
    (100246, '{"title":"Kiểm tra nhanh: @Transactional","questions":[{"question":"Mặc định Spring rollback khi gặp loại ngoại lệ nào?","options":["Mọi Exception","Chỉ RuntimeException và Error","Chỉ checked exception","Không tự rollback"],"correctOptionIndex":1,"explanation":"Mặc định chỉ rollback với unchecked exception; muốn rollback cho checked exception phải khai báo rollbackFor."},{"question":"Gọi một phương thức @Transactional từ chính bên trong cùng lớp thì sao?","options":["Vẫn mở giao dịch bình thường","Proxy bị bỏ qua nên không có giao dịch","Ném lỗi khi khởi động","Tạo giao dịch lồng nhau"],"correctOptionIndex":1,"explanation":"Giao dịch được cài qua proxy; gọi nội bộ không đi qua proxy nên annotation không có tác dụng."},{"question":"readOnly = true mang lại lợi ích rõ nhất nào?","options":["Tăng tốc ghi","Hibernate bỏ qua dirty checking","Tự động thêm index","Nén dữ liệu trả về"],"correctOptionIndex":1,"explanation":"Không cần so sánh trạng thái trước và sau nên tiết kiệm cả bộ nhớ lẫn thời gian ở cuối giao dịch."}]}'::jsonb),
    (100305, '{"title":"Kiểm tra nhanh: Index Postgres","questions":[{"question":"Partial index là gì?","options":["Index chỉ trên các hàng thoả điều kiện WHERE","Index chia theo phân vùng","Index chứa một phần giá trị cột","Index tạm trong bộ nhớ"],"correctOptionIndex":0,"explanation":"Partial index chỉ lập chỉ mục cho hàng khớp mệnh đề WHERE, nên nhỏ và rẻ hơn nhiều."},{"question":"Thứ tự cột trong index tổ hợp có quan trọng không?","options":["Không, Postgres tự sắp lại","Có, truy vấn phải dùng tiền tố trái","Chỉ với index UNIQUE","Chỉ khi có ORDER BY"],"correctOptionIndex":1,"explanation":"Index B-tree tổ hợp chỉ dùng được khi điều kiện phủ từ cột đầu tiên trở đi."},{"question":"GIN index hợp với kiểu dữ liệu nào?","options":["integer","jsonb và mảng","boolean","timestamp"],"correctOptionIndex":1,"explanation":"GIN thiết kế cho giá trị chứa nhiều phần tử con như jsonb, mảng và full-text search."}]}'::jsonb),
    (100330, '{"title":"Kiểm tra nhanh: React Hooks","questions":[{"question":"useEffect không truyền mảng phụ thuộc thì chạy khi nào?","options":["Chỉ một lần khi mount","Sau mỗi lần render","Không bao giờ chạy","Chỉ khi unmount"],"correctOptionIndex":1,"explanation":"Thiếu mảng phụ thuộc nghĩa là effect chạy lại sau mọi lần render."},{"question":"useMemo dùng để làm gì?","options":["Ghi nhớ kết quả tính toán tốn kém","Thay thế useState","Gọi API","Quản lý route"],"correctOptionIndex":0,"explanation":"useMemo giữ lại kết quả và chỉ tính lại khi phụ thuộc thay đổi."},{"question":"Vì sao không gọi hook trong vòng lặp hay câu điều kiện?","options":["Vì cú pháp không cho phép","Vì React khớp state theo thứ tự gọi hook","Vì gây rò rỉ bộ nhớ","Vì hook chỉ chạy trên server"],"correctOptionIndex":1,"explanation":"React khớp state với hook theo thứ tự gọi; thứ tự đổi giữa các lần render là state gắn nhầm chỗ."}]}'::jsonb),
    (100846, '{"title":"Kiểm tra nhanh: Docker","questions":[{"question":"Khác nhau giữa image và container là gì?","options":["Không khác, chỉ là tên gọi","Image là bản mẫu chỉ đọc, container là tiến trình chạy từ nó","Container nhẹ hơn image","Image chạy được, container thì không"],"correctOptionIndex":1,"explanation":"Image là các lớp chỉ đọc; container thêm một lớp ghi được và một tiến trình."},{"question":"COPY khác ADD ở điểm nào?","options":["Không khác gì","ADD giải nén tar và tải được URL","COPY nhanh hơn","ADD chỉ dùng cho thư mục"],"correctOptionIndex":1,"explanation":"ADD làm thêm hai việc ngầm, nên COPY được khuyến nghị khi không cần hai việc đó."},{"question":"Vì sao nên gộp lệnh RUN?","options":["Để mã ngắn hơn","Vì mỗi RUN tạo một lớp image mới","Vì Docker giới hạn số RUN","Không nên gộp"],"correctOptionIndex":1,"explanation":"Mỗi chỉ thị tạo một lớp; gộp lại giảm số lớp và kích thước image cuối."}]}'::jsonb),
    (100862, '{"title":"Kiểm tra nhanh: Redis","questions":[{"question":"Sorted set dùng để làm gì trong bảng tin?","options":["Lưu phiên đăng nhập","Xếp hạng bài theo điểm và cắt trang","Nén dữ liệu","Thay thế database"],"correctOptionIndex":1,"explanation":"ZADD gán điểm, ZREVRANGE cắt trang — đúng hình dạng của một bảng tin."},{"question":"SETEX khác SET ở chỗ nào?","options":["Ghi nhanh hơn","Đặt kèm thời gian sống","Ghi vào đĩa ngay","Chỉ ghi nếu chưa tồn tại"],"correctOptionIndex":1,"explanation":"SETEX gộp SET và EXPIRE thành một lệnh, tránh trạng thái key không có TTL."},{"question":"Vì sao không nên dùng KEYS trên production?","options":["Vì trả sai kết quả","Vì nó quét toàn bộ không gian khoá và chặn server","Vì cần quyền admin","Vì đã bị gỡ bỏ"],"correctOptionIndex":1,"explanation":"Redis chạy một luồng; KEYS quét toàn bộ và chặn mọi lệnh khác trong lúc đó."}]}'::jsonb),
    (100967, '{"title":"Kiểm tra nhanh: HTTP","questions":[{"question":"Mã 401 khác 403 thế nào?","options":["Giống nhau","401 là chưa xác thực, 403 là đã xác thực nhưng không đủ quyền","401 là lỗi server","403 nghĩa là không tìm thấy"],"correctOptionIndex":1,"explanation":"401 nói ''bạn là ai?'', 403 nói ''biết bạn là ai rồi, nhưng không cho''."},{"question":"PUT khác PATCH ở điểm nào?","options":["Không khác","PUT thay toàn bộ tài nguyên, PATCH sửa một phần","PATCH nhanh hơn","PUT không có body"],"correctOptionIndex":1,"explanation":"PUT mang ngữ nghĩa thay thế nguyên vẹn, nên thiếu trường là xoá trường đó."},{"question":"Idempotent nghĩa là gì?","options":["Chạy nhanh","Gọi nhiều lần cho cùng kết quả như gọi một lần","Không có tác dụng phụ nào","Luôn trả 200"],"correctOptionIndex":1,"explanation":"Đó là lý do webhook cần khoá idempotency: mạng lỗi thì bên gửi sẽ thử lại."}]}'::jsonb),
    (101319, '{"title":"Kiểm tra nhanh: Kiểm thử","questions":[{"question":"Vì sao test không nên phụ thuộc thứ tự chạy?","options":["Vì chạy chậm hơn","Vì đỏ ngẫu nhiên và rất khó tái hiện","Vì trình chạy không hỗ trợ","Vì tốn bộ nhớ"],"correctOptionIndex":1,"explanation":"Test phụ thuộc thứ tự sẽ đỏ khi ai đó thêm một test mới ở giữa, chẳng liên quan gì tới thay đổi của họ."},{"question":"Testcontainers giải quyết vấn đề gì so với H2?","options":["Chạy nhanh hơn","Chạy trên đúng database mà production dùng","Không cần Docker","Tự sinh dữ liệu"],"correctOptionIndex":1,"explanation":"H2 không có unaccent, không có jsonb như Postgres, nên test xanh mà production vẫn hỏng."},{"question":"Mock quá nhiều dẫn tới điều gì?","options":["Test chạy chậm","Test kiểm chứng chính cái mock chứ không phải hệ thống","Không biên dịch được","Tăng độ phủ giả"],"correctOptionIndex":1,"explanation":"Khi mọi cộng tác viên đều là mock, test chỉ còn chứng minh rằng bạn đã viết đúng cái mock."}]}'::jsonb),
    (101405, '{"title":"Kiểm tra nhanh: Flyway","questions":[{"question":"Vì sao không được sửa một migration đã apply?","options":["Vì file bị khoá","Vì checksum lệch và validate-on-migrate sẽ chặn khởi động","Vì Flyway xoá file cũ","Không sao cả"],"correctOptionIndex":1,"explanation":"Chuyện này đã một lần làm production không khởi động được — xem README của db/seed."},{"question":"Flyway phân giải version thế nào khi có nhiều location?","options":["Mỗi location một dãy riêng","Một dãy duy nhất cho tất cả","Theo thứ tự khai báo","Theo thời gian sửa file"],"correctOptionIndex":1,"explanation":"Vì vậy trùng số giữa db/seed và db/migration là lỗi khởi động, không phải cảnh báo."},{"question":"placeholder được thay ở giai đoạn nào?","options":["Sau khi parse SQL","Khi đọc file, trước khi parse","Lúc commit","Không bao giờ"],"correctOptionIndex":1,"explanation":"Nên một placeholder chưa khai nằm trong dòng comment cũng đủ giết migration."}]}'::jsonb)
  ) AS v(id, details)
 WHERE p.id = v.id;

-- Đẩy sequence quá dải id gán tay.

SELECT setval('socialapp.q_posts_id', 102601, FALSE);
